cat > /root/pi_workspace/frida_java_scaffold.js << 'EOF'
// Frida Java hook 脚手架(IDAdroid 插件生成)
Java.perform(function () {
    var TARGET = Java.use('{{cls}}');
    try {
        TARGET.{{method}}.implementation = function () {
            var args = [].slice.call(arguments);
            console.log('[+] {{cls}}.{{method}} called with: ' + JSON.stringify(args));
            var ret = this.{{method}}.apply(this, args);
            console.log('[=] return: ' + ret);
            return ret;
        };
    } catch (e) { console.log('[-] hook 失败: ' + e); }
});
EOF
cat /root/pi_workspace/frida_java_scaffold.js
